package com.vandorlabs.neoforge.segmented;
import com.vandorlabs.neoforge.ModernFinishCatalog;
import com.vandorlabs.segmented.SegmentedCellArtwork;
import com.vandorlabs.redstone.ChannelList;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.*;
import net.minecraft.core.component.DataComponents;
/** Installed canonical menu and per-cell publication checks, followed by a separate-process read. */
final class SegmentedCellArtworkHostChecks {
 private static void need(boolean value,String why){if(!value)throw new AssertionError("Segmented cell artwork: "+why);}
 private static int choice(int at){for(int i=0;i<ModernFinishCatalog.ENTRIES.size();i++)if(NativeSegmentedDoorEntity.validTexture(i)&&at--==0)return i;throw new AssertionError("two actual materials required");}
 private static NativeSegmentedDoorEntity tile(ServerLevel world,BlockPos pos){return (NativeSegmentedDoorEntity)world.getBlockEntity(pos);}
 private static void open(ServerLevel world,ServerPlayer actor,BlockPos pos){actor.setPos(pos.getX()+.5,pos.getY()+.5,pos.getZ()-2);need(NativeSegmentedConfiguration.open(actor,world,pos,NativeSegmentedRegistrations.MENU.get()),"shared installed menu opener");}
 private static void edit(ServerPlayer actor,int operation,int choice){var selected=(NativeSegmentedMenu)actor.containerMenu;var command=new NativeSegmentedEdit(selected.containerId,operation,10,true,true,ChannelList.EMPTY,choice,null);var bytes=io.netty.buffer.Unpooled.buffer();try{command.encode(bytes);need(NativeSegmentedMenu.apply(actor,NativeSegmentedEdit.decode(bytes,NativeSegmentedDoorEntity::validTexture)),"bounded roundtrip reaches actual selected menu");}finally{bytes.release();}}
 static void write(ServerLevel world,ServerPlayer actor,BlockPos base){int a=choice(0),b=choice(1);open(world,actor,base);edit(actor,6,a);need(tile(world,base).effectiveTexture()==a&&tile(world,base).cellArtwork().overridden&&!tile(world,base.above()).cellArtwork().overridden,"local choice leaves peer inherited");open(world,actor,base.above());edit(actor,6,b);need(tile(world,base).effectiveTexture()==a&&tile(world,base.above()).effectiveTexture()==b,"different artwork in one column");var visual=tile(world,base.above(2)).publication().visual();need(visual.texture(2)==a&&visual.texture(1)==b,"immutable per-row artwork publication");edit(actor,7,-1);need(!tile(world,base.above()).cellArtwork().overridden&&tile(world,base).cellArtwork().overridden,"reset only selected cell");edit(actor,3,b);for(int x=0;x<3;x++)for(int y=0;y<3;y++)need(!tile(world,base.offset(x,y,0)).cellArtwork().overridden&&tile(world,base.offset(x,y,0)).effectiveTexture()==b,"explicit all clears overrides");open(world,actor,base);edit(actor,6,a);open(world,actor,base.above());edit(actor,6,b);var picked=NativeSegmentedItem.pick(NativeSegmentedRegistrations.ITEM.get(),tile(world,base));need(picked.get(DataComponents.CUSTOM_DATA).copyTag().getCompound(NativeSegmentedItem.CONFIGURATION).getInt(SegmentedCellArtwork.FIELD)==a,"actual configured pick retains cell choice");var copied=com.vandorlabs.neoforge.copifier.NativeCopifierSegmentedEdit.capture(tile(world,base).copiedState());var target=tile(world,base.east());actor.setPos(target.getBlockPos().getX()+.5,target.getBlockPos().getY()+.5,target.getBlockPos().getZ()-2);need(target.configureCopied(copied,actor)&&target.cellArtwork().overridden&&target.effectiveTexture()==a,"actual copied configuration retains local choice");var converted=com.vandorlabs.neoforge.copifier.NativeCopifierCraftingItems.apply(new net.minecraft.world.item.ItemStack(NativeSegmentedRegistrations.ITEM.get()),copied,world.registryAccess());need(!converted.isEmpty()&&converted.get(DataComponents.CUSTOM_DATA).copyTag().getCompound(NativeSegmentedItem.CONFIGURATION).getInt(SegmentedCellArtwork.FIELD)==a,"actual copied-item recipe converter retains local choice");System.out.println("[vandorlabs][segmented-cell-artwork] write PASS canonical/menu/per-row/reset/all/pick");}
 static void read(ServerLevel world,BlockPos base){world.getChunkAt(base);need(tile(world,base).cellArtwork().overridden&&tile(world,base).effectiveTexture()==choice(0)&&tile(world,base.above()).cellArtwork().overridden&&tile(world,base.above()).effectiveTexture()==choice(1),"restart retains distinct cell choices across unrelated mechanism edits");System.out.println("[vandorlabs][segmented-cell-artwork] read PASS distinct-cell ownership");}
}
